# Check for 2x2 block adjacency (they share an edge)
def are_adjacent(b1, b2):
    i1, j1 = b1
    i2, j2 = b2
    # Two 2x2 are adjacent if they can form a bigger connected block
    # Check the 4 corners of each
    for bi in [i1, i1+1]:
        for bj in [j1, j1+1]:
            for bi2 in [i2, i2+1]:
                for bj2 in [j2, j2+1]:
                    if bi != bi2 or bj != bj2:
                        continue
                    if (bi, bj) == (i2, j2) or (bi, bj) == (i2, j2+1) or \
                       (bi, bj) == (i2+1, j2) or (bi, j1) == (i2, j2) or \
                       (bi, bj) == (i1+1, j2) or (bi, bj) == (i1, j2+1) or \
                       (bi, bj) == (i1-1, j2) or (bi, bj) == (i1, j2-1):
                        pass

    # Simpler: check if any cell in block1 is adjacent to any in block2
    for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
        if i2 in [i1+di, i1+di+1] and j2 in [j1+dj, j1+dj+1]:
            return True
    if i2 in [i1, i1+1] and j2 in [j1+1, j1]:
        return True
    if j2 in [j1, j1+1] and i2 in [i1+1, i1]:
        return True
    return False

def find_item_adjacency(blocks):
    """For each block, count how many other blocks it's adjacent to"""
    adj = {}
    for b in blocks:
        count = 0
        for b2 in blocks:
            if b == b2:
                continue
            if are_adjacent(b, b2):
                count += 1
        adj[b] = count
    return adj

